"""Three signed input points and native settling for an energy current kernel."""
from pathlib import Path
import hashlib,json,subprocess
import numpy as np
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 cell='gf180_energy_square_kernel_v1';folder=BASE/'layout'/cell;qp=folder/'qualification.json';fp=folder/'flat_cap_qualification.json';q=json.loads(qp.read_text());f=json.loads(fp.read_text());assert q['magic_drc_count']==0 and q['lvs_unique'] and f['flat_lvs_unique'] and not f['negative_aggregate_branches'];files={Path(__file__),qp,fp}
 for n,h in f['sha256'].items():
  if Path(n).suffix!='.ext':assert sha(ROOT/n)==h,n
  files.add(ROOT/n)
 flat=folder/(f['flat_subcircuit']+'_cap.spice');files.add(flat);model=BASE/'pdk/gf180_primitive_source/models/ngspice';files.update(model.rglob('*.spice'));prefix='/workspace/'+model.relative_to(ROOT).as_posix();stem=cell+'_nominal_src'+sha(Path(__file__))[:12];rp=BASE/'results'/(stem+'.json');assert not rp.exists();dp=BASE/'results'/(stem+'_dc.dat');tp=BASE/'results'/(stem+'_transient.dat')
 lines=['Native balanced quadratic kernel',f'.include {prefix}/design.spice',f'.lib {prefix}/sm141064.spice typical','.param sw_stat_global=0 sw_stat_mismatch=0','.temp 27','.options method=gear reltol=1e-6 abstol=1e-16 vntol=1e-10 gmin=1e-18',flat.read_text().replace(f['flat_subcircuit'],cell),'.global VSUBS','Vsub VSUBS 0 0','Vdd vdd 0 3.3','Vbase base 0 .9','Vdelta delta 0 PWL(0 0 4.99u 0 5u .1 9.99u .1 10u -.1 14.99u -.1 15u 0 20u 0)','Eplus inp base delta 0 1','Eminus inn base delta 0 -1','Vout output 0 1.65',f'Xkernel inp inn base output vdd 0 {cell}','.control','set numdgt=15','set wr_singlescale','set wr_vecnames','dc Vdelta -.1 .1 .1','wrdata /workspace/'+dp.relative_to(ROOT).as_posix()+' v(delta) v(inp) v(inn) i(Vout)','reset','tran .005u 20u 0 .02u uic','wrdata /workspace/'+tp.relative_to(ROOT).as_posix()+' v(delta) v(inp) v(inn) i(Vout)','quit','.endc','.end'];deck=BASE/'benches'/(stem+'.spice');deck.write_text('\n'.join(lines)+'\n');files.add(deck);snap=BASE/'tools/source_snapshots'/(stem+'.py');snap.write_bytes(Path(__file__).read_bytes());files.add(snap)
 run=subprocess.run(['docker','run','--rm','--network','none','--memory','2g','--cpus','2','--volume',f'{ROOT}:/workspace','--workdir','/workspace','--entrypoint','timeout','eventspikeseg:analog-ngspice47','120','ngspice','-b','/workspace/'+deck.relative_to(ROOT).as_posix()],capture_output=True,text=True,timeout=135);log=run.stdout+run.stderr;lp=BASE/'results'/(stem+'.log');lp.write_text(log);files.add(lp)
 r={'module_simulation_completed':False,'simulator_returncode':run.returncode,'scope':'Native6MOS quadratic candidate with physical common-current balance. Three inputs -0.1,0,+0.1V around0.9V; external ideal differential formatting and1.65V output-voltage fixture, typical27C. Three-point even-response/settling characterization only; not quadratic linearity/range proof, candidate/adaptation subtraction, normalization, square root, clamp or trained RMS/strength implementation. DC offset/current compliance must remain visible. No model precision/population5ms/full-chip acceptance.','quadratic_current_map_accepted':False,'complete_RMS_accepted':False}
 try:
  d=np.loadtxt(dp,skiprows=1);t=np.loadtxt(tp,skiprows=1);files.update([dp,tp]);ok=bool(run.returncode==0 and d.shape==(3,5) and t.shape[1]==5 and np.isfinite(d).all() and np.isfinite(t).all() and abs(t[-1,0]-20e-6)<1e-15 and 'aborted' not in log.lower());r['module_simulation_completed']=ok
  if ok:
   current=-d[:,4];offset=float(current[1]);inc=current-offset;sample=lambda us:float(-np.interp(us*1e-6,t[:,0],t[:,4]));r['cases']=[{'case':tag,'differential_input_v':float(d[i,0]),'net_sink_current_a':float(current[i]),'increment_from_zero_a':float(inc[i])} for i,tag in enumerate(['negative','zero','positive'])];r['zero_input_offset_a']=offset;r['increment_polarity_asymmetry_a']=float(inc[2]-inc[0]);r['symmetric_positive_increment_observed']=bool(inc[0]>0 and inc[2]>0 and abs(inc[2]-inc[0])<1e-3*max(abs(inc[0]),abs(inc[2])));r['plateau_net_sink_currents_a']={str(us):sample(us) for us in [4.5,9.5,14.5,19.5]}
 except Exception as e:r['postprocess_error']=str(e)
 r['sha256']={p.relative_to(ROOT).as_posix():sha(p) for p in sorted(files)};rp.write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({'report':str(rp),**{k:v for k,v in r.items() if k!='sha256'}},indent=2));assert r['module_simulation_completed']
